counts = {}
for letter in "banana":
    counts[letter] = counts.get(letter, 0) + 1
print(counts)

groups = {}
for n in [3, 8, 5, 2, 10, 7]:
    key = "even" if n % 2 == 0 else "odd"
    groups.setdefault(key, []).append(n)
print(groups)

base = {"color": "blue", "size": "medium", "rounded": False}
custom = {"size": "large", "rounded": True}
theme = base | custom
print(theme)

theme.update({"color": "green"})
print(theme)

